}
func TestReviewLegacyDetails(t *testing.T) {
 msg := &legacy.SearchRequestV3{Query:"legacy detail"}
 st, err := status.New(codes.Internal,"failure").WithDetails(msg); if err != nil {t.Fatal(err)}
 got := st.Details(); if len(got)!=1 {t.Fatalf("Details length=%d",len(got))}
 typed, ok := got[0].(*legacy.SearchRequestV3)
 if !ok {t.Fatalf("Details returned %T, want *grpc_testing_not_regenerate.SearchRequestV3",got[0])}
